// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PosCatalog Каталог для кассы
	// (GET /catalog)
	PosCatalog(ctx context.Context, request PosCatalogRequestObject) (PosCatalogResponseObject, error)
	// PosCheck Проверить позицию перед добавлением в чек
	// (POST /checks)
	PosCheck(ctx context.Context, request PosCheckRequestObject) (PosCheckResponseObject, error)
	// PosFindReceipts Найти чек продажи для возврата
	// (GET /receipts)
	PosFindReceipts(ctx context.Context, request PosFindReceiptsRequestObject) (PosFindReceiptsResponseObject, error)
	// PosCreateReceipt Чек продажи или возврата
	// (POST /receipts)
	PosCreateReceipt(ctx context.Context, request PosCreateReceiptRequestObject) (PosCreateReceiptResponseObject, error)
	// PosLogout Выход кассира
	// (DELETE /session)
	PosLogout(ctx context.Context, request PosLogoutRequestObject) (PosLogoutResponseObject, error)
	// PosLogin Вход кассира по логину и PIN
	// (POST /session)
	PosLogin(ctx context.Context, request PosLoginRequestObject) (PosLoginResponseObject, error)
	// PosCurrentShift Открытая смена кассы
	// (GET /shift)
	PosCurrentShift(ctx context.Context, request PosCurrentShiftRequestObject) (PosCurrentShiftResponseObject, error)
	// PosOpenShift Открыть смену
	// (POST /shift)
	PosOpenShift(ctx context.Context, request PosOpenShiftRequestObject) (PosOpenShiftResponseObject, error)
	// PosCloseShift Закрыть смену
	// (POST /shift/close)
	PosCloseShift(ctx context.Context, request PosCloseShiftRequestObject) (PosCloseShiftResponseObject, error)
	// PosTime Время сервера и окна продажи алкоголя на сегодня
	// (GET /time)
	PosTime(ctx context.Context, request PosTimeRequestObject) (PosTimeResponseObject, error)
}

type StrictHandlerFunc func(ctx *echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

